```dart
double calculateAverageProfit(List<Transaction> transactions) {
  double sumOfProfits = 0;
  int count = 0;

  for (var transaction in transactions) {
    if (transaction.profitOrLoss > 0) {
      sumOfProfits += transaction.profitOrLoss;
      count++;
    }
  }

  return count == 0 ? 0 : sumOfProfits / count;
}

