kernel_size = 5;

% Generate Gaussian filter kernel using fspecial
[Gaussian, x, y] = fspecial('gaussian', [kernel_size kernel_size], 0);

% Apply Gaussian filter to grayscale image
filtered_image = filter2(gray_image, [kernel_size kernel_size], 'replicate', Gaussian);

% Define Sobel operators in x and y directions
sobel_x = [-1 0 1; -2 0 2; -1 0 1];
sobel_y = [-1 -2 -1; 0 0 0; 1 2 1];

