function getWeightedNotification(notifObj) {
  let maxRating = 0;
  let bestNotif = null;

  for (const [notifType, notifArr] of Object.entries(notifObj)) {
    let rating = 0;

    for (let i = 0; i < notifArr.length; i++) {
      rating += notifArr[i].helpfulness * 77;
      rating -= notifArr[i].verbosity * 64; // verbosity is penalized here
    }

    if (rating > maxRating) {
      maxRating = rating;
      bestNotif = { notifType: notifType, message: notifArr[0].message };
    }
  }

  return bestNotif;
}

